int total_energy(int cells[], int n)
{
    int totalValueSoFar = 0;
    int currentIndex = n - 1;
    int loopIsRunning = 1;
    if (currentIndex >= 0)
    {
        while (loopIsRunning == 1)
        {
            totalValueSoFar = totalValueSoFar + cells[currentIndex];
            currentIndex = currentIndex - 1;
            if (currentIndex < 0)
            {
                loopIsRunning = 0;
            }
            else
            {
                loopIsRunning = 1;
            }
        }
    }
    else
    {
        totalValueSoFar = 0;
    }
    return totalValueSoFar;
}
